import{_ as a,a0 as e,w as l,s as p,I as r,x as t,a1 as i,A as o,ao as u}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse('{"title":"UNIX 家族小史 | LCTT x X-CMD","titleTemplate":false,"description":"UNIX 家族小史 | LCTT (201512) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"UNIX 家族小史 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"UNIX 家族小史 | LCTT (201512) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201512/20151012 The Brief History Of Aix HP-UX Solaris BSD And LINUX","title":"UNIX 家族小史","tag":"201512","desc":""},"relativePath":"201512/20151012 The Brief History Of Aix HP-UX Solaris BSD And LINUX.md","filePath":"[post].md"}'),g={name:"201512/20151012 The Brief History Of Aix HP-UX Solaris BSD And LINUX.md"};function x(S,n,X,d,m,U){const s=e("Link");return l(),p("div",null,[n[22]||(n[22]=r("h1",{id:"unix-家族小史",tabindex:"-1"},[t("UNIX 家族小史 "),r("a",{class:"header-anchor",href:"#unix-家族小史","aria-label":"Permalink to “UNIX 家族小史”"},"​")],-1)),n[23]||(n[23]=r("p",null,[r("img",{src:"http://1426826955.rsc.cdn77.org/wp-content/uploads/2015/05/linux-712x445.png",alt:""})],-1)),r("p",null,[n[2]||(n[2]=t("要记住，当一扇门在你面前关闭的时候，另一扇门就会打开。肯·汤普森（",-1)),i(s,{href:"http://www.unixmen.com/ken-thompson-unix-systems-father/"},{default:o(()=>[...n[0]||(n[0]=[t("Ken Thompson",-1)])]),_:1}),n[3]||(n[3]=t("） 和丹尼斯·里奇（",-1)),i(s,{href:"http://www.unixmen.com/dennis-m-ritchie-father-c-programming-language/"},{default:o(()=>[...n[1]||(n[1]=[t("Dennis Richie",-1)])]),_:1}),n[4]||(n[4]=t("） 两个人就是这句名言很好的实例。他们俩是",-1)),n[5]||(n[5]=r("strong",null,"20世纪",-1)),n[6]||(n[6]=t("最优秀的信息技术专家之二，因为他们创造了最具影响力和创新性的软件之一： ",-1)),n[7]||(n[7]=r("strong",null,"UNIX",-1)),n[8]||(n[8]=t("。",-1))]),n[24]||(n[24]=u('<h3 id="unix-系统诞生于贝尔实验室" tabindex="-1">UNIX 系统诞生于贝尔实验室 <a class="header-anchor" href="#unix-系统诞生于贝尔实验室" aria-label="Permalink to “UNIX 系统诞生于贝尔实验室”">​</a></h3><p><strong>UNIX</strong> 最开始的名字是 <strong>UNICS</strong> (<strong>UN</strong>iplexed <strong>I</strong>nformation and <strong>C</strong>omputing <strong>S</strong>ervice)，它有一个大家庭，并不是从石头缝里蹦出来的。UNIX的祖父是 <strong>CTSS</strong> (<strong>C</strong>ompatible <strong>T</strong>ime <strong>S</strong>haring <strong>S</strong>ystem)，它的父亲是 <strong>Multics</strong> (<strong>MULT</strong>iplexed <strong>I</strong>nformation and <strong>C</strong>omputing <strong>S</strong>ervice)，这个系统能支持大量用户通过交互式分时（timesharing）的方式使用大型机。</p><p>UNIX 诞生于 <strong>1969</strong> 年，由<strong>肯·汤普森</strong>以及后来加入的<strong>丹尼斯·里奇</strong>共同完成。这两位优秀的研究员和科学家在一个<strong>通用电器 GE</strong>和<strong>麻省理工学院</strong>的合作项目里工作，项目目标是开发一个叫 Multics 的交互式分时系统。</p><p>Multics 的目标是整合分时技术以及当时其他先进技术，允许用户在远程终端通过电话（拨号）登录到主机，然后可以编辑文档，阅读电子邮件，运行计算器，等等。</p><p>在之后的五年里，AT&amp;T 公司为 Multics 项目投入了数百万美元。他们购买了 GE-645 大型机，聚集了贝尔实验室的顶级研究人员，例如肯·汤普森、 Stuart Feldman、丹尼斯·里奇、道格拉斯·麦克罗伊（M. Douglas McIlroy）、 Joseph F. Ossanna 以及 Robert Morris。但是项目目标太过激进，进度严重滞后。最后，AT&amp;T 高层决定放弃这个项目。</p><p>贝尔实验室的管理层决定停止这个让许多研究人员无比纠结的操作系统上的所有遗留工作。不过要感谢汤普森，里奇和一些其他研究员，他们把老板的命令丢到一边，并继续在实验室里满怀热心地忘我工作，最终孵化出前无古人后无来者的 UNIX。</p><p>UNIX 的第一声啼哭是在一台 PDP-7 微型机上，它是汤普森测试自己在操作系统设计上的点子的机器，也是汤普森和 里奇一起玩 Space and Travel 游戏的模拟器。</p><blockquote><p>“我们想要的不仅是一个优秀的编程环境，而是能围绕这个系统形成团体。按我们自己的经验，通过远程访问和分时主机实现的公共计算，本质上不只是用终端输入程序代替打孔机而已，而是鼓励密切沟通。”丹尼斯·里奇说。</p></blockquote><p>UNIX 是第一个靠近理想的系统，在这里程序员可以坐在机器前自由摆弄程序，探索各种可能性并随手测试。在 UNIX 整个生命周期里，它吸引了大量因其他操作系统限制而投身过来的高手做出无私贡献，因此它的功能模型一直保持上升趋势。</p><p>UNIX 在 1970 年因为 PDP-11/20 获得了首次资金注入，之后正式更名为 UNIX 并支持在 PDP-11/20 上运行。UNIX 带来的第一次用于实际场景中是在 1971 年，贝尔实验室的专利部门配备来做文字处理。</p><h3 id="unix-上的-c-语言革命" tabindex="-1">UNIX 上的 C 语言革命 <a class="header-anchor" href="#unix-上的-c-语言革命" aria-label="Permalink to “UNIX 上的 C 语言革命”">​</a></h3><p>丹尼斯·里奇在 1972 年发明了一种叫 “<strong>C</strong>” 的高级编程语言 ，之后他和肯·汤普森决定用 “C” 重写 UNIX 系统，来支持更好的移植性。他们在那一年里编写和调试了差不多 100,000 行代码。在迁移到 “C” 语言后，系统可移植性非常好，只需要修改一小部分机器相关的代码就可以将 UNIX 移植到其他计算机平台上。</p><p>UNIX 第一次公开露面是 1973 年丹尼斯·里奇和肯·汤普森在操作系统原理（Operating Systems Principles）上发表的一篇论文，然后 AT&amp;T 发布了 UNIX 系统第 5 版，并授权给教育机构使用，之后在 1975 年第一次以 <strong>$20.000</strong> 的价格授权企业使用 UNIX 第 6 版。应用最广泛的是 1980 年发布的 UNIX 第 7 版，任何人都可以购买授权，只是授权条款非常严格。授权内容包括源代码，以及用 PDP-11 汇编语言写的及其相关内核。反正，各种版本 UNIX 系统完全由它的用户手册确定。</p><h3 id="aix-系统" tabindex="-1">AIX 系统 <a class="header-anchor" href="#aix-系统" aria-label="Permalink to “AIX 系统”">​</a></h3><p>在 <strong>1983</strong> 年，<strong>微软</strong>计划开发 <strong>Xenix</strong> 作为 MS-DOS 的多用户版继任者，他们在那一年花了 $8,000 搭建了一台拥有 <strong>512 KB</strong> 内存以及 <strong>10 MB</strong>硬盘并运行 Xenix 的 Altos 586。而到 1984 年为止，全世界 UNIX System V 第二版的安装数量已经超过了 100,000 。在 1986 年发布了包含因特网域名服务的 4.3BSD，而且 <strong>IBM</strong> 宣布 <strong>AIX 系统</strong>的安装数已经超过 250,000。AIX 基于 Unix System V 开发，这套系统拥有 BSD 风格的根文件系统，是两者的结合。</p><p>AIX 第一次引入了 <strong>日志文件系统 (JFS)</strong> 以及集成逻辑卷管理器 (Logical Volume Manager ，LVM)。IBM 在 1989 年将 AIX 移植到自己的 RS/6000 平台。2001 年发布的 5L 版是一个突破性的版本，提供了 Linux 友好性以及支持 Power4 服务器的逻辑分区。</p><p>在 2004 年发布的 AIX 5.3 引入了支持高级电源虚拟化（ Advanced Power Virtualization，APV）的虚拟化技术，支持对称多线程、微分区，以及共享处理器池。</p><p>在 2007 年，IBM 同时发布 AIX 6.1 和 Power6 架构，开始加强自己的虚拟化产品。他们还将高级电源虚拟化重新包装成 PowerVM。</p><p>这次改进包括被称为 WPARs 的负载分区形式，类似于 Solaris 的 zones/Containers，但是功能更强。</p><h3 id="hp-ux-系统" tabindex="-1">HP-UX 系统 <a class="header-anchor" href="#hp-ux-系统" aria-label="Permalink to “HP-UX 系统”">​</a></h3><p><strong>惠普 UNIX (Hewlett-Packard’s UNIX，HP-UX)</strong> 源于 System V 第 3 版。这套系统一开始只支持 PA-RISC HP 9000 平台。HP-UX 第 1 版发布于 1984 年。</p><p>HP-UX 第 9 版引入了 SAM，一个基于字符的图形用户界面 (GUI)，用户可以用来管理整个系统。在 1995 年发布的第 10 版，调整了系统文件分布以及目录结构，变得有点类似 AT&amp;T SVR4。</p><p>第 11 版发布于 1997 年。这是 HP 第一个支持 64 位寻址的版本。不过在 2000 年重新发布成 11i，因为 HP 为特定的信息技术用途，引入了操作环境（operating environments）和分级应用（layered applications）的捆绑组（bundled groups）。</p><p>在 2001 年发布的 11.20 版宣称支持安腾（Itanium）系统。HP-UX 是第一个使用 ACLs（访问控制列表，Access Control Lists）管理文件权限的 UNIX 系统，也是首先支持内建逻辑卷管理器（Logical Volume Manager）的系统之一。</p><p>如今，HP-UX 因为 HP 和 Veritas 的合作关系使用了 Veritas 作为主文件系统。</p><p>HP-UX 目前的最新版本是 11iv3, update 4。</p><h3 id="solaris-系统" tabindex="-1">Solaris 系统 <a class="header-anchor" href="#solaris-系统" aria-label="Permalink to “Solaris 系统”">​</a></h3><p>Sun 的 UNIX 版本是 <strong>Solaris</strong>，用来接替 1992 年创建的 <strong>SunOS</strong>。SunOS 一开始基于 BSD（伯克利软件发行版，Berkeley Software Distribution）风格的 UNIX，但是 SunOS 5.0 版以及之后的版本都是基于重新包装为 Solaris 的 Unix System V 第 4 版。</p><p>SunOS 1.0 版于 1983 年发布，用于支持 Sun-1 和 Sun-2 平台。随后在 1985 年发布了 2.0 版。在 1987 年，Sun 和 AT&amp;T 宣布合作一个项目以 SVR4 为基础将 System V 和 BSD 合并成一个版本。</p><p>Solaris 2.4 是 Sun 发布的第一个 Sparc/x86 版本。1994 年 11 月份发布的 SunOS 4.1.4 版是最后一个版本。Solaris 7 是首个 64 位 Ultra Sparc 版本，加入了对文件系统元数据记录的原生支持。</p><p>Solaris 9 发布于 2002 年，支持 Linux 特性以及 Solaris 卷管理器（Solaris Volume Manager）。之后，2005 年发布了 Solaris 10，带来许多创新，比如支持 Solaris Containers，新的 ZFS 文件系统，以及逻辑域（Logical Domains）。</p><p>目前 Solaris 最新的版本是 第 10 版，最后的更新发布于 2008 年。</p><h3 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to “Linux”">​</a></h3><p>到了 1991 年，用来替代商业操作系统的自由（free）操作系统的需求日渐高涨。因此，<strong>Linus Torvalds</strong> 开始构建一个自由的操作系统，最终成为 <strong>Linux</strong>。Linux 最开始只有一些 “C” 文件，并且使用了阻止商业发行的授权。Linux 是一个类 UNIX 系统但又不尽相同。</p><p>2015 年发布了基于 GNU Public License （GPL）授权的 3.18 版。IBM 声称有超过 1800 万行开源代码开源给开发者。</p><p>如今 GNU Public License 是应用最广泛的自由软件授权方式。根据开源软件原则，这份授权允许个人和企业自由分发、运行、通过拷贝共享、学习，以及修改软件源码。</p><h3 id="unix-vs-linux-技术概要" tabindex="-1">UNIX vs. Linux：技术概要 <a class="header-anchor" href="#unix-vs-linux-技术概要" aria-label="Permalink to “UNIX vs. Linux：技术概要”">​</a></h3><ul><li>Linux 鼓励多样性，Linux 的开发人员来自各种背景，有更多不同经验和意见。</li><li>Linux 比 UNIX 支持更多的平台和架构。</li><li>UNIX 商业版本的开发人员针对特定目标平台以及用户设计他们的操作系统。</li><li><strong>Linux 比 UNIX 有更好的安全性</strong>，更少受病毒或恶意软件攻击。截止到现在，Linux 上大约有 60-100 种病毒，但是没有任何一种还在传播。另一方面，UNIX 上大约有 85-120 种病毒，但是其中有一些还在传播中。</li><li>由于 UNIX 命令、工具和元素很少改变，甚至很多接口和命令行参数在后续 UNIX 版本中一直沿用。</li><li>有些 Linux 开发项目以自愿为基础进行资助，比如 Debian。其他项目会维护一个和商业 Linux 的社区版，比如 SUSE 的 openSUSE 以及红帽的 Fedora。</li><li>传统 UNIX 是纵向扩展，而另一方面 Linux 是横向扩展。</li></ul><hr>',39)),r("p",null,[n[10]||(n[10]=t("via: ",-1)),i(s,{href:"http://www.unixmen.com/brief-history-aix-hp-ux-solaris-bsd-linux/"},{default:o(()=>[...n[9]||(n[9]=[t("http://www.unixmen.com/brief-history-aix-hp-ux-solaris-bsd-linux/",-1)])]),_:1})]),r("p",null,[n[14]||(n[14]=t("作者：",-1)),i(s,{href:"http://www.unixmen.com/author/pirat9/"},{default:o(()=>[...n[11]||(n[11]=[t("M.el Khamlichi",-1)])]),_:1}),n[15]||(n[15]=t(" 译者：",-1)),i(s,{href:"https://github.com/zpl1025"},{default:o(()=>[...n[12]||(n[12]=[t("zpl1025",-1)])]),_:1}),n[16]||(n[16]=t(" 校对：",-1)),i(s,{href:"https://github.com/carolinewuyan"},{default:o(()=>[...n[13]||(n[13]=[t("Caroline",-1)])]),_:1})]),r("p",null,[n[19]||(n[19]=t("本文由 ",-1)),i(s,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...n[17]||(n[17]=[t("LCTT",-1)])]),_:1}),n[20]||(n[20]=t(" 原创编译，",-1)),i(s,{href:"https://linux.cn/"},{default:o(()=>[...n[18]||(n[18]=[t("Linux中国",-1)])]),_:1}),n[21]||(n[21]=t(" 荣誉推出",-1))])])}const P=a(g,[["render",x]]);export{f as __pageData,P as default};
